public class Q26_Thread_Sleep_Two_Seconds { public static void main(String[] args){ Thread sleeper=new Thread(()->{try{System.out.println("Sleeper starts");Thread.sleep(2000);System.out.println("Sleeper wakes after 2 seconds");}catch(InterruptedException e){Thread.currentThread().interrupt();}}); Thread worker=new Thread(()->{for(int i=1;i<=5;i++)System.out.println("Worker continues: "+i);}); sleeper.start();worker.start(); } }
